const REST = 'http://localhost:5555';
const inp = $input.first().json;

// --- Parse input (handle nested 'query' JSON string from agent tool calls) ---
let programCode = inp.programCode || '';
let inputLabels = inp.inputLabels || {};
let outputLabels = inp.outputLabels || {};
let testPlan = inp.testPlan || {};

if (typeof inp.query === 'string') {
  try {
    const parsed = JSON.parse(inp.query);
    if (!programCode) programCode = parsed.programCode || '';
    if (Object.keys(inputLabels).length === 0) inputLabels = parsed.inputLabels || {};
    if (Object.keys(outputLabels).length === 0) outputLabels = parsed.outputLabels || {};
    if (Object.keys(testPlan).length === 0) testPlan = parsed.testPlan || {};
  } catch {}
}
// inputLabels/outputLabels/testPlan may arrive as JSON strings
if (typeof inputLabels === 'string') { try { inputLabels = JSON.parse(inputLabels); } catch { inputLabels = {}; } }
if (typeof outputLabels === 'string') { try { outputLabels = JSON.parse(outputLabels); } catch { outputLabels = {}; } }
if (typeof testPlan === 'string') { try { testPlan = JSON.parse(testPlan); } catch { testPlan = {}; } }

if (!programCode) {
  return [{ json: { deployed: false, passed: false, error: 'programCode missing in input', receivedInputKeys: Object.keys(inp) } }];
}

// --- Normalize code: strip // and ; comments, trim leading/trailing whitespace per line, drop empty lines ---
function normalizeFpcCode(src) {
  const out = [];
  for (let raw of src.split(/\r?\n/)) {
    let line = raw;
    // Strip // comments (everything after //)
    const slashIdx = line.indexOf('//');
    if (slashIdx >= 0) line = line.slice(0, slashIdx);
    // Trim leading + trailing whitespace
    line = line.trim();
    // Drop empty lines
    if (!line) continue;
    // Keep # comments as-is (FPC native comment)
    out.push(line);
  }
  return out.join('\n');
}
const originalCode = programCode;
programCode = normalizeFpcCode(programCode);

const log = [];
log.push({ step: 'normalizeCode', originalLines: originalCode.split(/\r?\n/).length, finalLines: programCode.split('\n').length });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function http(method, path, body, contentType) {
  const opts = {
    method,
    url: REST + path,
    returnFullResponse: true,
    json: contentType === 'application/json',
  };
  if (body !== undefined) {
    opts.body = body;
    opts.headers = { 'Content-Type': contentType || 'application/json' };
  }
  try {
    const r = await this.helpers.httpRequest(opts);
    let b = r && r.body !== undefined ? r.body : r;
    if (typeof b === 'string') { try { b = JSON.parse(b); } catch {} }
    return { ok: true, status: r?.statusCode || 200, body: b };
  } catch (e) {
    return { ok: false, status: e.statusCode || 0, error: e.message || String(e), body: e.cause?.error || null };
  }
}

async function getInputs() {
  const r = await http('GET', '/api/inputs');
  const arr = Array(20).fill(0);
  if (r.ok && Array.isArray(r.body?.inputs)) {
    for (const o of r.body.inputs) if (o.index < arr.length) arr[o.index] = o.value ? 1 : 0;
  }
  return arr;
}

async function getOutputs() {
  const r = await http('GET', '/api/outputs');
  const arr = Array(20).fill(0);
  let okFlag = false;
  if (r.ok && Array.isArray(r.body?.outputs)) {
    okFlag = true;
    for (const o of r.body.outputs) if (o.index < arr.length) arr[o.index] = o.value ? 1 : 0;
  }
  return { arr, ok: okFlag };
}

async function setInput(idx, val) {
  const inputs = await getInputs();
  const target = val ? 1 : 0;
  if (inputs[idx] !== target) {
    await http('POST', '/api/inputs/' + idx + '/toggle');
  }
}

// --- 0. Stop + Debug-Modus deaktivieren (falls vom Debugger hinterlassen) ---
await http('POST', '/api/stop');
const debugRes = await http('POST', '/api/debug', 'false', 'application/json');
log.push({ step: 'disableDebug', debugEnabled: debugRes.body?.debugEnabled, ok: debugRes.ok });

// --- 1. Stop ---
const stopRes = await http('POST', '/api/stop');
log.push({ step: 'stop', status: stopRes.status, ok: stopRes.ok });

// --- 2. Set labels (must be when stopped) ---
for (const [idx, label] of Object.entries(inputLabels)) {
  if (!label) continue;
  const r = await http('PUT', '/api/inputs/' + idx + '/label', String(label), 'text/plain');
  log.push({ step: 'setInputLabel', idx, label, status: r.status, ok: r.ok, error: r.error });
}
for (const [idx, label] of Object.entries(outputLabels)) {
  if (!label) continue;
  const r = await http('PUT', '/api/outputs/' + idx + '/label', String(label), 'text/plain');
  log.push({ step: 'setOutputLabel', idx, label, status: r.status, ok: r.ok, error: r.error });
}

// --- 3. Load program ---
const loadRes = await http('POST', '/api/program', programCode, 'text/plain');
log.push({ step: 'loadProgram', status: loadRes.status, ok: loadRes.ok, body: loadRes.body, error: loadRes.error });

if (!loadRes.ok) {
  return [{ json: { deployed: false, passed: false, error: 'POST /api/program failed', log } }];
}

// --- 4. Verify ---
const verRes = await http('GET', '/api/program');
const hasParseError = verRes.body?.hasParseError === true;
const isExecutable = verRes.body?.isExecutable === true;
log.push({ step: 'verify', isExecutable, hasParseError, parseErrorMessage: verRes.body?.parseErrorMessage || null });

if (hasParseError || !isExecutable) {
  return [{ json: {
    deployed: false,
    passed: false,
    error: 'Program not executable',
    parseErrorMessage: verRes.body?.parseErrorMessage,
    log
  } }];
}

// --- 5. Reset inputs ---
const resetInputs = testPlan.resetInputs || [];
for (const ri of resetInputs) {
  await setInput(ri.index, ri.value);
  log.push({ step: 'resetInput', idx: ri.index, value: !!ri.value });
}

// --- 6. Start ---
const startRes = await http('POST', '/api/start');
log.push({ step: 'start', status: startRes.status, ok: startRes.ok });
if (!startRes.ok) {
  return [{ json: { deployed: false, passed: false, error: 'start failed', log } }];
}
const startTime = Date.now();

// --- 7. Run cycle samples ---
const samples = (testPlan.samples || []).slice().sort((a, b) => (a.tMs || 0) - (b.tMs || 0));
const cycleResults = [];
for (const s of samples) {
  const wait = (s.tMs || 0) - (Date.now() - startTime);
  if (wait > 0) await sleep(wait);
  const { arr: actual, ok } = await getOutputs();
  const expected = s.outputs || s.expected || [];
  const diffs = [];
  for (let i = 0; i < expected.length; i++) {
    if (actual[i] !== expected[i]) diffs.push({ O: i, expected: expected[i], actual: actual[i] });
  }
  cycleResults.push({
    label: s.label || ('t=' + (s.tMs || 0) + 'ms'),
    tMs: s.tMs || 0,
    actualElapsedMs: Date.now() - startTime,
    expected,
    actual: actual.slice(0, Math.max(expected.length, 3)),
    httpOk: ok,
    pass: ok && diffs.length === 0,
    diffs
  });
}

// --- 8. NOTAUS test (optional) ---
let notausResult = null;
const nt = testPlan.notausTest;
if (nt && nt.index !== undefined) {
  await http('POST', '/api/stop');
  await setInput(nt.index, true);
  await http('POST', '/api/start');
  const stabMs = Math.max(300, nt.stabiliseMs || 600);
  await sleep(stabMs);
  const { arr: actual, ok } = await getOutputs();
  const expected = nt.expected || [];
  const diffs = [];
  for (let i = 0; i < expected.length; i++) {
    if (actual[i] !== expected[i]) diffs.push({ O: i, expected: expected[i], actual: actual[i] });
  }
  notausResult = {
    label: nt.label || 'NOTAUS',
    expected,
    actual: actual.slice(0, Math.max(expected.length, 3)),
    httpOk: ok,
    pass: ok && diffs.length === 0,
    diffs
  };
  await http('POST', '/api/stop');
  await setInput(nt.index, false);
}

// --- 9. Final stop, leave controller in idle stopped state ---
await http('POST', '/api/stop');

const passCycle = cycleResults.filter((r) => r.pass).length;
const total = cycleResults.length + (notausResult ? 1 : 0);
const passed = (passCycle === cycleResults.length) && (notausResult ? notausResult.pass : true);
const failed = total - passCycle - (notausResult && notausResult.pass ? 1 : 0);

return [{
  json: {
    deployed: true,
    passed,
    summary: passed
      ? ('ALLE ' + total + ' TESTS BESTANDEN')
      : (failed + ' von ' + total + ' FEHLGESCHLAGEN — Code korrigieren und neu deployen+testen'),
    sourceLines: verRes.body?.sourceLines,
    cycleResults,
    notausResult,
    log
  }
}];
